Stack: Node 20+, Express, `better-sqlite3`. Hashing via stdlib `crypto.scrypt`, so no extra dependency.

```js
// server.js — npm i express better-sqlite3 cookie-parser
const express = require('express');
const cookieParser = require('cookie-parser');
const Database = require('better-sqlite3');
const crypto = require('node:crypto');
const { promisify } = require('node:util');
const scrypt = promisify(crypto.scrypt);

const db = new Database('auth.db');
db.pragma('journal_mode = WAL');
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL UNIQUE COLLATE NOCASE,
    pw_hash TEXT NOT NULL,
    created_at INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS sessions (
    token_hash TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS login_failures (
    key TEXT PRIMARY KEY,
    count INTEGER NOT NULL,
    window_start INTEGER NOT NULL,
    locked_until INTEGER NOT NULL DEFAULT 0
  );
`);

// --- password hashing (scrypt, N=2^15) ---
const SCRYPT = { N: 2 ** 15, r: 8, p: 1, maxmem: 64 * 1024 * 1024 };
async function hashPassword(pw) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(pw, salt, 64, SCRYPT);
  return `scrypt$${SCRYPT.N}$${SCRYPT.r}$${SCRYPT.p}$${salt.toString('base64')}$${key.toString('base64')}`;
}
async function verifyPassword(pw, stored) {
  const [, N, r, p, saltB64, keyB64] = stored.split('$');
  const expected = Buffer.from(keyB64, 'base64');
  const key = await scrypt(pw, Buffer.from(saltB64, 'base64'), expected.length,
    { N: +N, r: +r, p: +p, maxmem: SCRYPT.maxmem });
  return crypto.timingSafeEqual(key, expected);
}
// Burn equal time for unknown emails → no user enumeration via timing
const DUMMY_HASH_P = hashPassword(crypto.randomBytes(16).toString('hex'));

// --- sessions: random token to client, only SHA-256 of it stored ---
const SESSION_TTL_MS = 7 * 24 * 3600 * 1000;
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
function issueSession(res, userId) {
  const token = crypto.randomBytes(32).toString('base64url');
  db.prepare('INSERT INTO sessions VALUES (?, ?, ?)')
    .run(sha256(token), userId, Date.now() + SESSION_TTL_MS);
  res.cookie('sid', token, {
    httpOnly: true, secure: true, sameSite: 'lax', path: '/', maxAge: SESSION_TTL_MS,
  });
}
function requireAuth(req, res, next) {
  const token = req.cookies.sid;
  if (!token) return res.sendStatus(401);
  const row = db.prepare('SELECT user_id, expires_at FROM sessions WHERE token_hash = ?')
    .get(sha256(token));
  if (!row || row.expires_at < Date.now()) return res.sendStatus(401);
  req.userId = row.user_id;
  next();
}

// --- rate limiting on failures: per email AND per IP ---
const MAX_FAILS = 5, WINDOW_MS = 15 * 60 * 1000, LOCK_MS = 15 * 60 * 1000;
const IP_MAX_FAILS = 50;
function isLocked(key) {
  const row = db.prepare('SELECT locked_until FROM login_failures WHERE key = ?').get(key);
  return row && row.locked_until > Date.now();
}
const recordFailure = db.transaction((key, max) => {
  const now = Date.now();
  const row = db.prepare('SELECT * FROM login_failures WHERE key = ?').get(key);
  if (!row || now - row.window_start > WINDOW_MS) {
    db.prepare('INSERT OR REPLACE INTO login_failures VALUES (?, 1, ?, 0)').run(key, now);
    return;
  }
  const count = row.count + 1;
  db.prepare('UPDATE login_failures SET count = ?, locked_until = ? WHERE key = ?')
    .run(count, count >= max ? now + LOCK_MS : 0, key);
});
const clearFailures = (key) => db.prepare('DELETE FROM login_failures WHERE key = ?').run(key);

// --- input validation ---
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function parseCreds(body) {
  const email = typeof body?.email === 'string' ? body.email.trim().toLowerCase() : '';
  const password = typeof body?.password === 'string' ? body.password : '';
  if (!EMAIL_RE.test(email) || email.length > 254) return null;
  // max length bounds hashing cost (DoS guard)
  if (password.length < 12 || password.length > 256) return null;
  return { email, password };
}

// --- routes ---
const app = express();
app.set('trust proxy', 1); // only if behind exactly one trusted proxy
app.use(express.json({ limit: '10kb' }));
app.use(cookieParser());

app.post('/signup', async (req, res) => {
  const creds = parseCreds(req.body);
  if (!creds) return res.status(400).json({ error: 'Invalid email or password (min 12 chars)' });
  const pwHash = await hashPassword(creds.password);
  try {
    const { lastInsertRowid } = db.prepare(
      'INSERT INTO users (email, pw_hash, created_at) VALUES (?, ?, ?)'
    ).run(creds.email, pwHash, Date.now());
    issueSession(res, lastInsertRowid);
    res.status(201).json({ ok: true });
  } catch (e) {
    if (e.code === 'SQLITE_CONSTRAINT_UNIQUE') return res.status(409).json({ error: 'Account exists' });
    throw e;
  }
});

app.post('/login', async (req, res) => {
  const creds = parseCreds(req.body);
  if (!creds) return res.status(400).json({ error: 'Invalid credentials' });
  const emailKey = `email:${creds.email}`, ipKey = `ip:${req.ip}`;

  if (isLocked(emailKey) || isLocked(ipKey)) {
    return res.status(429).json({ error: 'Too many attempts, try later' });
  }

  const user = db.prepare('SELECT id, pw_hash FROM users WHERE email = ?').get(creds.email);
  const ok = await verifyPassword(creds.password, user ? user.pw_hash : await DUMMY_HASH_P);

  if (!user || !ok) {
    recordFailure(emailKey, MAX_FAILS);
    recordFailure(ipKey, IP_MAX_FAILS);
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  clearFailures(emailKey);
  // Session fixation guard: always issue a fresh token
  issueSession(res, user.id);
  res.json({ ok: true });
});

app.post('/logout', (req, res) => {
  if (req.cookies.sid) db.prepare('DELETE FROM sessions WHERE token_hash = ?').run(sha256(req.cookies.sid));
  res.clearCookie('sid', { path: '/' });
  res.sendStatus(204);
});

app.get('/me', requireAuth, (req, res) => {
  res.json(db.prepare('SELECT id, email FROM users WHERE id = ?').get(req.userId));
});

setInterval(() => db.prepare('DELETE FROM sessions WHERE expires_at < ?').run(Date.now()), 3600_000).unref();

app.listen(3000);
```

Main choices:
- Session tokens are stored as hashes, so a DB leak doesn't hand out live sessions.
- Unknown emails get a dummy hash compare → equal timing, same generic 401.
- Lockout runs per email (5 / 15 min) and per IP (50) → covers both targeted guessing and credential stuffing.

Not included:
- CSRF tokens. `SameSite=lax` covers most cases; add tokens if you have cross-site form posts.
- Signup's 409 reveals which emails are registered. If that matters, switch to an email-verification flow that always returns the same response.
- The lockout lets an attacker lock a victim's account. If that's a concern, swap the hard lock for a CAPTCHA or exponential delay.
